const changes=new Map();
const choose=(p,options,expected,why)=>({id:'decision-v5',type:'choose',prompt:T(...p),options:options.map((x,i)=>I('c'+i,...x)),expected:expected.map(i=>'c'+i),reason:T(...why)});
const order=(p,items,why)=>({id:'sequence-v5',type:'order',prompt:T(...p),items:items.map((x,i)=>I('s'+i,...x)).reverse(),expected:items.map((_,i)=>'s'+i),reason:T(...why)});
const sort=(p,bins,items,why)=>({id:'classify-v5',type:'sort',prompt:T(...p),bins:bins.map((x,i)=>I('b'+i,...x)),items:items.map((x,i)=>({...I('i'+i,x[0],x[1]),target:'b'+x[2]})),reason:T(...why)});
function replace(id,why,rounds){changes.set(id,{why:T(...why),rounds});}

